from pathlib import Path
p=Path('create_review_deck.py')
s=p.read_text(encoding='utf-8-sig')
needle="prs.save(OUT)\nprint(OUT)"
insert='''# Narrative slides requested for the college review deck. Added after the detailed content, then moved directly behind the title slide.\n# project definition\ns=base("What is this project?")\ntextbox(s,.8,1.5,11.7,.65,"We are building and evaluating an intrusion-detection research system that selects models under practical CPU, latency and size limits, then studies whether it can recover when network traffic changes.",20,WHITE,True,align=PP_ALIGN.CENTER)\nnode(s,.8,3.0,2.15,1.3,"TRAFFIC","Public labeled network flows",CYAN); node(s,3.3,3.0,2.15,1.3,"AUTO-SELECT","Features + model under budgets",BLUE); node(s,5.8,3.0,2.15,1.3,"DETECT","Benign vs attack",GREEN); node(s,8.3,3.0,2.15,1.3,"MONITOR","Drift, FPR, calibration",AMBER); node(s,10.8,3.0,1.75,1.3,"ADAPT","Labels then update",PURPLE)\nfor i in range(4): arrow(s,2.96+2.5*i,3.65,3.26+2.5*i,3.65)\ncard(s,1.0,5.0,5.25,1.0,"RESEARCH GOAL","Prove what works, under which data and resource conditions.",CYAN,13); card(s,7.0,5.0,5.25,1.0,"DELIVERABLE VISION","AutoShield AI: a monitor-first interface around a validated engine.",GREEN,13)\n# base paper abstract paraphrase\ns=base("Starting point: the base paper and its abstract")\ntextbox(s,.8,1.35,11.8,.55,"Yang & Shami — Toward Autonomous and Efficient Cybersecurity: A Multi-Objective AutoML-based Intrusion Detection System (IEEE TMLCN, 2025)",16,CYAN,True)\ncard(s,.8,2.15,7.15,2.85,"ABSTRACT — FAITHFUL PARAPHRASE","The paper proposes an AutoML-based IDS for increasingly sophisticated threats and resource-constrained IoT settings. Its framework combines automated feature selection (OIP-AutoFS) with joint classifier selection and hyperparameter optimization (OPCE-CASH), using multi-objective optimization to balance detection performance, confidence-related measures and computational efficiency. It evaluates the approach on CICIDS2017 and IoTID20 and reports improvements over its evaluated IDS baselines.",17,14)\ncard(s,8.35,2.15,4.1,2.85,"HOW OUR PROJECT STARTS","Reproduce the authors’ repository notebooks, then test the system’s resource tradeoffs and behavior on ordered traffic. We preserve the base work as provenance; our extensions are separate experiments.",GREEN,15)\ntextbox(s,.9,5.35,11.5,.7,"Paper abstract paraphrased for presentation. Source: Yang & Shami, arXiv:2511.08491; DOI: 10.1109/TMLCN.2025.3631379. The paper’s “outperforms” statement summarizes its own reported benchmark results, not our independent verification.",10,MUTED)\n# stage roadmap, 2 slides\nstages1=[("v0.1","Project foundation","Read base paper, repository and scope; identify benchmark samples and intended MOO-AutoML pipeline.","DONE"),("v0.2","Faithful reproduction","Run and preserve two original notebooks; record their test-set-in-selection limitation.","DONE"),("v0.3","Evaluation redesign","Add fold-local, leakage-aware evaluation helpers and explicit metrics/resource accounting.","DONE"),("v0.4","Resource-aware search","Run CPU budget sweeps for model quality, calibration, latency and serialized size.","DONE"),("v0.5","Optimizer reality check","Compare MOPSO with random search and feasibility-first vs constraint-blind MOPSO; results mixed, no winner.","DONE") ]\ns=base("The project story | v0.1 → v0.5: build the foundation")\nfor i,(v,t,b,st) in enumerate(stages1):\n y=1.42+i*1.03; pill(s,.8,y,.9,v, GREEN); textbox(s,1.95,y-.02,2.5,.35,t,14,WHITE,True); textbox(s,4.5,y-.02,6.8,.5,b,12,MUTED); pill(s,11.55,y,.95,st,GREEN)\ntextbox(s,1.0,6.75,11,.25,"Story beat: reproduction became a measurement platform; the optimizer comparison challenged the assumption that MOPSO must win.",11,CYAN,True,align=PP_ALIGN.CENTER)\nstages2=[("v0.6","Real temporal replay","Acquire/audit all 10 CSE daily files; replay 15.18M valid rows in timestamp order, fixed CPU model.","DONE"),("v0.7","Adaptation study","Compare no-update, PSI, delayed-label error trigger, periodic refit and threshold-only controls; seeds and sensitivities.","DONE"),("v0.8","End-to-end transfer","Train on IoTID20, map 77 shared features, replay CSE with chunk labels revealed after scoring.","DONE"),("v0.9","Research gap & data gates","Audit closest work and candidate datasets; novelty unresolved; NF-ToN-v3 needs causal end-time ordering.","CURRENT"),("v1.0","Confirm, contribute, demonstrate","Lock a defensible new question; matched baselines + independent confirmation; build AutoShield monitor-first demo.","NEXT") ]\ns=base("The project story | v0.6 → v1.0: from results to a contribution")\nfor i,(v,t,b,st) in enumerate(stages2):\n y=1.42+i*1.03; col=AMBER if st=="CURRENT" else (MUTED if st=="NEXT" else GREEN); pill(s,.8,y,.9,v,col); textbox(s,1.95,y-.02,2.5,.35,t,14,WHITE,True); textbox(s,4.5,y-.02,6.8,.5,b,12,MUTED); pill(s,11.35,y,1.15,st,col)\ntextbox(s,1.0,6.75,11,.25,"We are at v0.9: evidence-rich development, but the core novelty and independent confirmation gate remain open.",12,AMBER,True,align=PP_ALIGN.CENTER)\n# Put story immediately after cover: definition, base, two stage maps, then existing executive summary and full deck.\nfrom pptx.oxml.ns import qn\nids=prs.slides._sldIdLst\nnew_items=list(ids)[-4:]\n# move the four newly created narrative slides to positions 2–5, keeping all earlier slides in order\nfor item in new_items: ids.remove(item)\nfor offset,item in enumerate(new_items): ids.insert(1+offset,item)\n\nprs.save(OUT)\nprint(OUT)'''
assert needle in s
p.write_text(s.replace(needle,insert),encoding='utf-8')
